from __future__ import annotations

import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest


ROOT = Path(__file__).resolve().parents[1]
CHECKER = ROOT / "check_trajectories.py"


def frame_text(time: str = "0", x: str = "0.1", z: str = "0.2", beads: int = 2) -> str:
    vectors = "\n".join(
        f"  <{x}, 0, {z}>{',' if i + 1 < beads else ''}" for i in range(beads)
    )
    return (
        "// Generated by make_trajectories.py -- do not edit.\n"
        f"#declare SimTime = {time};\n"
        "#declare TauRatio = 1;\n#declare CoreRadius = 0.32;\n"
        "#declare CoreHalfHeight = 0.55;\n#declare ActuatorPhase = 0;\n"
        f"#declare NBeads = {beads};\n#declare BeadPos = array[NBeads] {{\n"
        f"{vectors}\n}};\n"
    )


class TrajectoryCheckerTests(unittest.TestCase):
    def run_checker(self, directory: Path, frames: int = 2, beads: int = 2, *extra: str):
        return subprocess.run(
            [sys.executable, str(CHECKER), str(directory), "--frames", str(frames),
             "--beads", str(beads), *extra],
            cwd=ROOT, text=True, capture_output=True, check=False,
        )

    def write_frames(self, directory: Path, values: list[tuple[str, str, str]]) -> None:
        for index, (time, x, z) in enumerate(values, 1):
            (directory / f"frame{index:04d}.inc").write_text(
                frame_text(time, x, z), encoding="ascii"
            )

    def test_valid_motion_and_json_report(self) -> None:
        with tempfile.TemporaryDirectory() as raw:
            directory = Path(raw) / "positions"
            directory.mkdir()
            self.write_frames(directory, [("0", "0.1", "0.2"), ("1", "0.2", "0.2")])
            report = directory.parent / "report.json"
            result = self.run_checker(directory, 2, 2, "--json-report", str(report))
            self.assertEqual(result.returncode, 0, result.stderr)
            self.assertIn("motion: motion_observed", result.stdout)
            data = json.loads(report.read_text(encoding="utf-8"))
            self.assertTrue(data["pass"])
            self.assertTrue(data["motion_observed"])
            self.assertEqual(data["frames_checked"], 2)

    def test_one_frame_distinguished_from_no_motion(self) -> None:
        with tempfile.TemporaryDirectory() as raw:
            directory = Path(raw)
            self.write_frames(directory, [("0", "0.1", "0.2")])
            result = self.run_checker(directory, 1, 2)
            self.assertEqual(result.returncode, 0, result.stderr)
            self.assertIn("one_frame_input", result.stdout)

    def test_rejects_inventory_malformed_values_and_time(self) -> None:
        cases = [
            ([("0", "0.1", "0.2")], 2, "frame inventory mismatch"),
            ([("0", "nan", "0.2"), ("1", "0.2", "0.2")], 2, "malformed bead coordinate"),
            ([("1", "0.1", "0.2"), ("1", "0.2", "0.2")], 2, "not greater"),
        ]
        for values, frames, expected in cases:
            with self.subTest(expected=expected), tempfile.TemporaryDirectory() as raw:
                directory = Path(raw)
                self.write_frames(directory, values)
                result = self.run_checker(directory, frames, 2)
                self.assertNotEqual(result.returncode, 0)
                self.assertIn(expected, result.stderr)

    def test_rejects_duplicate_declaration_truncation_and_wrong_count(self) -> None:
        mutations = [
            lambda text: text.replace("#declare TauRatio = 1;", "#declare TauRatio = 1;\n#declare TauRatio = 1;"),
            lambda text: text[:-4],
            lambda text: text.replace("#declare NBeads = 2;", "#declare NBeads = 1;"),
        ]
        for mutate in mutations:
            with self.subTest(), tempfile.TemporaryDirectory() as raw:
                directory = Path(raw)
                (directory / "frame0001.inc").write_text(mutate(frame_text()), encoding="ascii")
                result = self.run_checker(directory, 1, 2)
                self.assertNotEqual(result.returncode, 0)

    def test_bounds_tolerance_and_source_preservation(self) -> None:
        with tempfile.TemporaryDirectory() as raw:
            directory = Path(raw)
            source = frame_text(x="0.9200000005")
            path = directory / "frame0001.inc"
            path.write_text(source, encoding="ascii")
            result = self.run_checker(directory, 1, 2)
            self.assertEqual(result.returncode, 0, result.stderr)
            self.assertEqual(path.read_text(encoding="ascii"), source)
            path.write_text(frame_text(x="0.920000002"), encoding="ascii")
            result = self.run_checker(directory, 1, 2)
            self.assertNotEqual(result.returncode, 0)

    def test_report_cannot_overwrite_input_or_existing_report(self) -> None:
        with tempfile.TemporaryDirectory() as raw:
            directory = Path(raw)
            input_path = directory / "frame0001.inc"
            input_path.write_text(frame_text(), encoding="ascii")
            original = input_path.read_text(encoding="ascii")
            result = self.run_checker(directory, 1, 2, "--json-report", str(input_path))
            self.assertNotEqual(result.returncode, 0)
            self.assertIn("overwrite input", result.stderr)
            self.assertEqual(input_path.read_text(encoding="ascii"), original)


if __name__ == "__main__":
    unittest.main()
